def calcular_frete(regiao, peso_kg):
    if regiao not in {"norte", "sul", "leste", "oeste"}:
        return "regiao invalida"

    if regiao == "norte":
        if peso_kg <= 5:
            return 12.5
        elif peso_kg <= 10:
            return 18.0
        return 25.0

    if regiao == "sul":
        if peso_kg <= 5:
            return 10.0
        elif peso_kg <= 10:
            return 15.5
        return 22.0

    if regiao == "leste":
        if peso_kg <= 5:
            return 11.0
        elif peso_kg <= 10:
            return 16.5
        return 24.0

    if peso_kg <= 5:
        return 13.0
    elif peso_kg <= 10:
        return 19.0
    return 27.0
